    local _z=table.concat(_x)
    local _alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local _map={}
    for i=1,#_alphabet do _map[string.byte(_alphabet,i)]=i-1 end
    local _out={}
    local _n=0
    local _xor=bit32 and bit32.bxor

    local function _showError(message)
        message=tostring(message or "Unknown error")
        warn("[VISION PRO 1.4.7 / STARTUP] "..message)
        pcall(function()
            local player=game:GetService("Players").LocalPlayer
            if not player then return end
            local playerGui=player:FindFirstChildOfClass("PlayerGui")
            if not playerGui then return end
            local previous=playerGui:FindFirstChild("VISION_PRO_STARTUP_ERROR")
            if previous then previous:Destroy() end
            local gui=Instance.new("ScreenGui")
            gui.Name="VISION_PRO_STARTUP_ERROR"
            gui.ResetOnSpawn=false
            gui.IgnoreGuiInset=true
            gui.DisplayOrder=9500
            gui.Parent=playerGui
            local panel=Instance.new("Frame")
            panel.AnchorPoint=Vector2.new(.5,.5)
            panel.Position=UDim2.fromScale(.5,.5)
            panel.Size=UDim2.fromOffset(500,195)
            panel.BackgroundColor3=Color3.fromRGB(29,34,51)
            panel.BorderSizePixel=0
            panel.Parent=gui
            local cr=Instance.new("UICorner")
            cr.CornerRadius=UDim.new(0,12)
            cr.Parent=panel
            local label=Instance.new("TextLabel")
            label.Position=UDim2.fromOffset(15,10)
            label.Size=UDim2.new(1,-30,0,132)
            label.BackgroundTransparency=1
            label.TextColor3=Color3.fromRGB(255,169,169)
            label.TextSize=14
            label.TextWrapped=true
            label.TextXAlignment=Enum.TextXAlignment.Left
            label.TextYAlignment=Enum.TextYAlignment.Top
            label.Font=Enum.Font.GothamMedium
            label.Text="VISION PRO v1.4.7 - ERREUR DE CHARGEMENT\n\n"..message:sub(1,550)
            label.Parent=panel
            local close=Instance.new("TextButton")
            close.Position=UDim2.fromOffset(15,150)
            close.Size=UDim2.new(1,-30,0,32)
            close.BackgroundColor3=Color3.fromRGB(78,105,149)
            close.Text="FERMER"
            close.TextSize=12
            close.Font=Enum.Font.GothamBold
            close.TextColor3=Color3.new(1,1,1)
            close.BorderSizePixel=0
            close.Parent=panel
            local c=Instance.new("UICorner")
            c.CornerRadius=UDim.new(0,8)
            c.Parent=close
            close.Activated:Connect(function() gui:Destroy() end)
        end)
