        return
    end
    local function _push(value)
        _n+=1
        _out[_n]=string.char(_xor(value,(_n*73+19)%256))
    end
    local ok,decodeError=pcall(function()
        for i=1,#_z,4 do
            local a=_map[string.byte(_z,i)]
            local b=_map[string.byte(_z,i+1)]
            local c=_map[string.byte(_z,i+2)]
            local d=_map[string.byte(_z,i+3)]
            if a==nil or b==nil then error("Incomplete GitHub file: encoded data corrupted") end
            _push(a*4+math.floor(b/16))
            if c~=nil then
                _push((b%16)*16+math.floor(c/4))
                if d~=nil then _push((c%4)*64+d) end
            end
        end
    end)
    if not ok then _showError(decodeError) return end
    if type(loadstring)~="function" then
        _showError("loadstring unavailable: cannot run an encoded Lua script")
        return
    end
    local loadOK,runner,compileError=pcall(loadstring,table.concat(_out))
    if not loadOK then
        _showError(runner)
        return
    end
    if type(runner)~="function" then
        _showError(compileError or "Luau compilation failed")
        return
    end
    local ran,result=xpcall(runner,function(err)
        local info=tostring(err)
        if debug and type(debug.traceback)=="function" then
            local ok,trace=pcall(debug.traceback,info,2)
            if ok and type(trace)=="string" then info=trace end
        end
        return info
    end)
    if not ran then
        _showError(result)
        return
    end
    return result
end
